Map<String, int> wordCounts(String text) {
  final normalized = text.trim().toLowerCase();
  final counts = <String, int>{};
  if (normalized.isEmpty) return counts;
  for (final word in normalized.split(RegExp(r'\s+'))) {
    counts.update(word, (count) => count + 1, ifAbsent: () => 1);
  }
  return counts;
}

