class CartLine {
  final String name;
  final int unitPriceCents;
  final int quantity;
  CartLine({required String name, required this.unitPriceCents, required this.quantity}) : name = name.trim() {
    if (this.name.isEmpty) throw ArgumentError('Name is required');
    if (unitPriceCents < 0) throw ArgumentError('Price must be nonnegative');
    if (quantity < 1) throw ArgumentError('Quantity must be positive');
  }
  int get totalCents => unitPriceCents * quantity;
}

